package com.opensocket.aievent.core.iam.api.response;import com.opensocket.aievent.core.iam.token.application.result.IssuedTokenResult;import java.time.Instant;import java.util.Set;
public record IssuedTokenResponse(String tokenId,String token,String tokenType,String prefix,String last4,Instant expiresAt,Set<String> permissions,Set<String> audiences,Set<String> apiPrefixes,Set<String> cidrs){public static IssuedTokenResponse from(IssuedTokenResult r){return new IssuedTokenResponse(r.tokenId(),r.token(),r.type().name(),r.prefix(),r.last4(),r.expiresAt(),r.effectiveScope().permissions(),r.effectiveScope().audiences(),r.effectiveScope().apiPrefixes(),r.effectiveScope().cidrs().stream().map(c->c.notation()).collect(java.util.stream.Collectors.toUnmodifiableSet()));}}
